// 第一批 20 篇是语文课本里的名篇 (17 篇在现在的统编课本里, 《五柳先生传》《游褒禅山记》《滕王阁序》在以前的人教版课本里);
// 第二批 13 篇: 补齐统编课本里的 7 篇, 加上成语多的 6 篇 (v1.55)。
// 注释照通行的课本讲法, 有两种讲法的写「一说」; 译文按原文一段对一段, 尽量直译。都是自己的话, 不抄别人的注释和译文。
// 2026-11 对照过: 原文对维基文库的《古文观止》(带吴楚材、吴调侯的评注) 和古诗文网; 注释、译文的讲法对古诗文网, 措辞跟它太像的改写过
//   '篇名' (书里有同名的两篇时写 '篇名|作者'): { notes: [{ at 在哪几个字里, w 注哪几个字 (at 里的, 不写就是 at 整个), note 解释 }], yi: [译文, 跟原文一段对一段],
//             cy: [{ w 成语或名句, kind 不写是成语 / '名句' / '词语', at 原文里的哪几个字 (不写: 从整篇来的, 像「世外桃源」), note 现在的意思 }],
//             zhi: [知道吗: 一句话, 或 { text, go: [书, 篇名] } 带一个去书库里另一篇的链接] }
//   成语只收出自这篇的; 化用别的书的 (「老当益壮」) 在 note 里写明「语本……」; 文中用了、但出自别的书的 (「鸡犬相闻」出自《老子》、「正襟危坐」出自《史记》) 不收
//   注释按原文的顺序写 (题目里的写在最前面); 每条从上一条注的字后面往下找 (见 reading.js 的 notesOf)
// tests/reading.test.js 会检查: 每条都找得到、译文跟原文一样多段
